diff --git a/index.js b/index.js
index 5ecd392..5ccc19c 100644
--- a/index.js
+++ b/index.js
@@ -81,7 +81,7 @@ export default function pLimit(concurrency) {
 					return;
 				}

-				const abortError = AbortSignal.abort().reason;
+				const abortError = createAbortError();

 				while (queue.size > 0) {
 					queue.dequeue().reject(abortError);
@@ -120,6 +120,14 @@ export function limitFunction(function_, options) {
 	return (...arguments_) => limit(() => function_(...arguments_));
 }

+function createAbortError() {
+	// Not `AbortSignal.abort().reason`, as that is a `DOMException`, which many
+	// error utilities (including `util.types.isNativeError`) do not treat as an error.
+	const error = new Error('This operation was aborted');
+	error.name = 'AbortError';
+	return error;
+}
